// The session (looked up by connection id) decodes the frame and classifies its
// root type. Bytes stay on msg.payload; the envelope never crosses a wire.
const S = global.get('ec').sessions.get(msg.conn);
msg.kind = S ? S.classifyBytes(msg.payload) : 'invalid';
return msg;

// Inbound EXECUTE_RESPONSE → route to the parked origination (leg-3 reverse
// authenticate / dispatch-outbound) by request_id (N7). Terminates here.
const S = global.get('ec').sessions.get(msg.conn);
if (S) S.routeResponseBytes(msg.payload);
return null;

// Neither EXECUTE nor EXECUTE_RESPONSE — the TS peer closes the connection here.
// Node-RED: drop (a socket-close hook is a follow-up robustness node).
return null;

const S = global.get('ec').sessions.get(msg.conn);
if (!S) { node.done(); return null; }
// decode → Execute → request_id → dispatch path → target-is-local (§1.4).
const r = S.dpBegin(msg.payload);
msg.did = r.did;
return r.route === 'ok' ? [msg, null] : [null, msg];

const S = global.get('ec').sessions.get(msg.conn);
if (!S) { node.done(); return null; }
// §4.2 the sole no-auth special case: connect + !established → connect handler.
const r = S.dpConnectPreauth(msg.did);
if (r === 'auth') return [msg, null, null];
if (r === 'connect') return [null, null, msg];
return [null, msg, null];

const S = global.get('ec').sessions.get(msg.conn);
if (!S) { node.done(); return null; }
// §5.1 authentication-class: a missing author is 401 missing_author; a request before the handshake completes is 401 authentication_failed (§4.7).
return S.dpAuthorPresent(msg.did) === 'ok' ? [msg, null] : [null, msg];

const S = global.get('ec').sessions.get(msg.conn);
if (!S) { node.done(); return null; }
// §5.1 authorization-class: a missing capability is 403 missing_authorization.
return S.dpCapPresent(msg.did) === 'ok' ? [msg, null] : [null, msg];

const S = global.get('ec').sessions.get(msg.conn);
if (!S) { node.done(); return null; }
// §6.5 ingest signatures + §5.2 verify (Ed25519 + capability-chain verdict,
// delegated leaf math). Denies 401/403/400 per the §5.2 sequence.
return S.dpVerify(msg.did) === 'ok' ? [msg, null] : [null, msg];

const S = global.get('ec').sessions.get(msg.conn);
if (!S) { node.done(); return null; }
// §6.6 route-by-path tree walk. No handler resolves → 404 handler_not_found.
return S.dpResolve(msg.did) === 'ok' ? [msg, null] : [null, msg];

const S = global.get('ec').sessions.get(msg.conn);
if (!S) { node.done(); return null; }
// §5.2 check_permission (permission verdict, delegated) + §6.8 handler-grant
// validation. Denies 403 capability_denied / permission_denied.
return S.dpPermission(msg.did) === 'ok' ? [msg, null] : [null, msg];

const S = global.get('ec').sessions.get(msg.conn);
if (!S) { node.done(); return null; }
S.dpRunHandler(msg.did).then((r) => { msg.payload = r.payload; msg.flipped = r.flipped; node.send(msg); node.done(); })
  .catch((e) => { node.error(e, msg); node.done(); });
return null;

const S = global.get('ec').sessions.get(msg.conn);
if (!S) { node.done(); return null; }
S.dpRunConnect(msg.did).then((r) => { msg.payload = r.payload; msg.flipped = r.flipped; node.send(msg); node.done(); })
  .catch((e) => { node.error(e, msg); node.done(); });
return null;

const S = global.get('ec').sessions.get(msg.conn);
if (!S) { node.done(); return null; }
// The short-circuit sink: encode the EXECUTE_RESPONSE error accumulated on the
// dispatch scratch (status/code/message) back to transport.
const r = S.dpBuildError(msg.did);
msg.payload = r.payload;
msg.flipped = r.flipped;
return msg;
